import pytest
from unittest.mock import MagicMock

class TestClusterAnalysis:
    def setup_method(self):
        self.cluster_analysis = ClusterAnalysis()  # Assuming the class name is ClusterAnalysis
        self.cluster_analysis.clustering_metrics = MagicMock(return_value=(0.5, 0.3, 0.2))
        self.cluster_analysis.get_biggest_cluster = MagicMock(return_value=([], []))
        self.cluster_analysis.biggest_cluster_metrics = MagicMock(return_value=(0, 0.1, 0.2, 0.3, 1.0))
        self.cluster_analysis.scaffold_analysis = MagicMock(return_value=(0, 0.1))
        self.cluster_analysis.get_clusters = MagicMock(return_value=[[], [], [], [], [], [], [], [], [], [], [], []])

    def test_forward_analysis_complete(self):
        clusters = self.cluster_analysis.forward()
        assert clusters == [[], [], [], [], [], [], [], [], [], [], [], []]
        assert self.cluster_analysis.chi_val == 0.5
        assert self.cluster_analysis.dbi_val == 0.3
        assert self.cluster_analysis.dunn_val == 0.2
        assert self.cluster_analysis.n_biggest_cluster == 0
        assert self.cluster_analysis.isim_biggest_cluster == 0.1
        assert self.cluster_analysis.isim_outliers == 0.2
        assert self.cluster_analysis.isim_medoids == 0.3
        assert self.cluster_analysis.radius_value == 1.0
        assert self.cluster_analysis.unique_scaffolds == 0
        assert self.cluster_analysis.scaffolds_iSIM == 0.1
        assert self.cluster_analysis.total_clusters == 12
        assert len(self.cluster_analysis.larger_clusters) == 2

    def test_no_clusters(self):
        self.cluster_analysis.get_clusters = MagicMock(return_value=[])
        clusters = self.cluster_analysis.forward()
        assert clusters == []
        assert self.cluster_analysis.total_clusters == 0
        assert len(self.cluster_analysis.larger_clusters) == 0

